import { useEffect, useMemo, useRef, useState, type FormEvent, type ReactNode } from "react";
import { Activity, AlertCircle, AlertTriangle, BarChart3, Bell, CheckCircle2, ChevronDown, ChevronLeft, ChevronRight, CircleDollarSign, CircleHelp, Cloud, Clock3, Command, Database, FileSearch, Gauge, LayoutDashboard, List, Map, MoreHorizontal, Pause, Play, RefreshCw, Search, ShieldCheck, SlidersHorizontal, StepForward, UserRound, X, Zap } from "lucide-react";
import { Area, AreaChart, Bar, BarChart, CartesianGrid, Cell, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";
import { ReactFlow, Background, Controls, Handle, Position, type Edge, type Node } from "@xyflow/react";
import "@xyflow/react/dist/style.css";

const API = import.meta.env.VITE_API_URL ?? "";
type Page = "overview" | "reports" | "incidents" | "costs";
type User = { username: string; role: string };
type LiveEvent = { type: string; eventId: number; receivedAt: number; [key: string]: any };
type StreamStatus = "connecting" | "connected" | "reconnecting" | "disconnected" | "expired";
const STREAM_EVENTS = ["demo.ready", "incident.detected", "incident.updated", "incident.acknowledged", "detection.triggered", "observation.received", "rca.queued", "rca.running", "rca.completed", "rca.fallback", "rca.status", "replay.started", "replay.progress", "replay.restarted", "replay.completed"];
function workspacePageSize() { const viewportHeight = typeof window === "undefined" ? 900 : window.innerHeight; if (viewportHeight < 800) return 6; if (viewportHeight < 980) return 8; if (viewportHeight < 1180) return 10; return 12; }

async function request(path: string, options: RequestInit = {}, token = "") {
  const headers = { "content-type": "application/json", ...(token ? { authorization: "Bearer " + token } : {}), ...(options.headers ?? {}) };
  const response = await fetch(API + path, { ...options, headers });
  if (!response.ok) {
    if (response.status === 401 && token) window.dispatchEvent(new Event("signalgrid-auth-expired"));
    throw new Error((await response.json().catch(() => ({}))).error ?? "Request failed (" + response.status + ")");
  }
  return response.json();
}
function fmt(value: unknown, digits = 1) { return value == null || Number.isNaN(value) ? "—" : typeof value === "number" ? value.toLocaleString(undefined, { maximumFractionDigits: digits }) : String(value); }
function money(value: unknown, digits = 2) { return value == null ? "—" : "$" + fmt(value, digits); }
function streamLabel(status: StreamStatus) { return status === "connected" ? "Connected" : status === "connecting" ? "Connecting" : status === "reconnecting" ? "Reconnecting" : status === "expired" ? "Session expired" : "Offline"; }
function displayStatus(value: unknown) { return String(value ?? "").replaceAll("_", " ").replace(/\b\w/g, character => character.toUpperCase()); }
function displayRole(role: string) {
  if (role === "ADMIN") return "Administrator";
  if (role === "ANALYST") return "Analyst";
  if (role === "OWNER" || role === "VIEWER") return "Owner";
  return displayStatus(role);
}

function useEventStream(token: string, onEvent: (event: LiveEvent) => void, onStatus: (status: StreamStatus) => void) {
  useEffect(() => {
    if (!token) { onStatus("disconnected"); return; }
    let source: EventSource | undefined; let cancelled = false; let reconnectTimer: number | undefined; let lastEventId = 0;
    const connect = async () => {
      if (cancelled) return;
      onStatus(source ? "reconnecting" : "connecting");
      try {
        const response = await fetch(API + "/api/events/ticket", { method: "POST", headers: { authorization: "Bearer " + token, "content-type": "application/json" } });
        if (response.status === 401) { onStatus("expired"); window.dispatchEvent(new Event("signalgrid-auth-expired")); return; }
        if (!response.ok) throw new Error("ticket");
        const data = await response.json(); if (cancelled || !data.ticket) return;
        source?.close();
        source = new EventSource(API + "/api/events?ticket=" + encodeURIComponent(data.ticket) + "&lastEventId=" + lastEventId);
        STREAM_EVENTS.forEach(name => source?.addEventListener(name, (event: MessageEvent) => {
          const eventId = Number(event.lastEventId || lastEventId); if (eventId && eventId <= lastEventId) return; if (eventId) lastEventId = eventId;
          let payload: Record<string, unknown> = {}; try { payload = JSON.parse(event.data); } catch { payload = { raw: String(event.data) }; }
          onEvent({ type: event.type, eventId, receivedAt: Date.now(), ...payload });
        }));
        source.onopen = () => onStatus("connected");
        source.onerror = () => { source?.close(); if (!cancelled) { onStatus("reconnecting"); reconnectTimer = window.setTimeout(connect, 750); } };
      } catch { if (!cancelled) { onStatus("reconnecting"); reconnectTimer = window.setTimeout(connect, 1000); } }
    };
    void connect();
    return () => { cancelled = true; if (reconnectTimer) window.clearTimeout(reconnectTimer); source?.close(); onStatus("disconnected"); };
  }, [token]);
}

export default function App() {
  const [route, setRoute] = useState(() => window.location.pathname || "/");
  const [page, setPage] = useState<Page>("overview");
  const [token, setToken] = useState(localStorage.getItem("signalgrid-token") ?? "");
  const [user, setUser] = useState<User | null>(null); const [error, setError] = useState(""); const [live, setLive] = useState<LiveEvent[]>([]); const [liveRevision, setLiveRevision] = useState(0); const [streamStatus, setStreamStatus] = useState<StreamStatus>("disconnected"); const [authChecked, setAuthChecked] = useState(!token); const [demoAuthEnabled, setDemoAuthEnabled] = useState(false); const [autoStartReplay, setAutoStartReplay] = useState(false);
  const navigate = (path: string) => { if (window.location.pathname !== path) window.history.pushState({}, "", path); setRoute(path); };
  useEffect(() => { const onPopState = () => setRoute(window.location.pathname || "/"); window.addEventListener("popstate", onPopState); return () => window.removeEventListener("popstate", onPopState); }, []);
  useEffect(() => { request("/api/auth/config").then(data => setDemoAuthEnabled(Boolean(data.demoAuthEnabled))).catch(() => undefined); }, []);
  useEffect(() => { const expire = () => { setToken(""); setUser(null); localStorage.removeItem("signalgrid-token"); setError("Your session expired. Please sign in again."); navigate("/signin"); }; window.addEventListener("signalgrid-auth-expired", expire); return () => window.removeEventListener("signalgrid-auth-expired", expire); }, []);
  useEffect(() => { if (!token) { setUser(null); setAuthChecked(true); return; } setAuthChecked(false); request("/api/auth/me", {}, token).then(data => { setUser(data.user); setAuthChecked(true); }).catch(() => { setToken(""); setUser(null); setAuthChecked(true); localStorage.removeItem("signalgrid-token"); }); }, [token]);
  useEffect(() => { if (user && route === "/signin") navigate(user.role === "ADMIN" ? "/admin/choose" : "/overview"); if (user?.role !== "ADMIN" && route === "/admin/choose") navigate("/overview"); }, [user, route]);
  useEventStream(token, event => { setLive(prev => [event, ...prev].slice(0, 24)); setLiveRevision(value => value + 1); }, setStreamStatus);
  const login = async (username: string, password: string) => { try { const data = await request("/api/auth/login", { method: "POST", body: JSON.stringify({ username, password }) }); setToken(data.token); localStorage.setItem("signalgrid-token", data.token); setError(""); navigate(data.user?.role === "ADMIN" ? "/admin/choose" : "/overview"); } catch { setError("Invalid username or password."); } };
  const logout = async () => { await request("/api/auth/logout", { method: "POST" }, token).catch(() => undefined); setToken(""); setUser(null); setLive([]); localStorage.removeItem("signalgrid-token"); navigate("/"); };
  if (!authChecked) return <Loading />;
  if (!user && route === "/signin") return <SignIn error={error} login={login} back={() => { setError(""); navigate("/"); }} demoAuthEnabled={demoAuthEnabled} />;
  if (!user) return <Landing onSignIn={() => { setError(""); navigate("/signin"); }} />;
  if (user.role === "ADMIN" && route === "/admin/choose") return <AdminChoose token={token} onReplay={async () => { await request("/api/replay/config", { method: "POST", body: JSON.stringify({ mode: "full", seed: 42, speed: 5, ordering: "sequential" }) }, token); setAutoStartReplay(true); navigate("/overview"); }} onAdminView={async () => { await request("/api/replay/evaluate", { method: "POST" }, token); setAutoStartReplay(false); navigate("/overview"); }} />;
  return <DashboardShellModern page={page} setPage={setPage} token={token} user={user} live={live} liveRevision={liveRevision} streamStatus={streamStatus} logout={logout} autoStartReplay={autoStartReplay} onReplayStarted={() => setAutoStartReplay(false)} />;
}

function SignalGridLogo({ compact = false, className = "" }: { compact?: boolean; className?: string }) {
  return <span className={"signalgrid-logo " + (compact ? "signalgrid-logo--compact " : "") + className} aria-label={compact ? "SignalGrid" : undefined} role={compact ? "img" : undefined}>
    <svg className="signalgrid-logo-mark" viewBox="0 0 44 54" aria-hidden="true">
      <path d="M10 2.5h19l11.5 11.5v32a5.5 5.5 0 0 1-5.5 5.5H10A5.5 5.5 0 0 1 4.5 46V8A5.5 5.5 0 0 1 10 2.5Z" fill="none" stroke="currentColor" strokeWidth="2.7" strokeLinejoin="round" />
      <path d="M29 3v11h11" fill="none" stroke="currentColor" strokeWidth="2.7" strokeLinejoin="round" />
      <path d="m11 38 7-7 5 4 10-11" fill="none" stroke="currentColor" strokeWidth="2.7" strokeLinecap="round" strokeLinejoin="round" />
      <circle cx="11" cy="38" r="1.8" fill="currentColor" /><circle cx="18" cy="31" r="1.8" fill="currentColor" /><circle cx="23" cy="35" r="1.8" fill="currentColor" /><circle cx="33" cy="24" r="1.8" fill="currentColor" />
    </svg>
    {!compact && <span className="signalgrid-logo-wordmark">SignalGrid</span>}
  </span>;
}

function SignalTimeline({ compact = false }: { compact?: boolean }) {
  const segments = Array.from({ length: 36 }, (_, index) => index);
  return <div className={"signal-timeline " + (compact ? "signal-timeline--compact" : "")} role="img" aria-label="SignalGrid workflow: Monitor, Detect, Investigate, Understand">
    <svg className="signal-timeline-svg" viewBox="0 0 1080 30" preserveAspectRatio="none" aria-hidden="true">
      <defs><linearGradient id="signal-glow" x1="0" y1="0" x2="1" y2="0"><stop offset="0" stopColor="#a6e8dc" /><stop offset=".42" stopColor="#08ad9d" /><stop offset=".67" stopColor="#ff9868" /><stop offset=".84" stopColor="#b9a9ee" /><stop offset="1" stopColor="#dfe9e7" /></linearGradient></defs>
      {segments.map(index => { const stage = index < 9 ? "monitor" : index < 18 ? "detect" : index < 27 ? "investigate" : "understand"; return <rect key={index} className={"signal-segment signal-segment--" + stage} x={index * 30 + 2} y="2" width="24" height="18" rx="6" style={{ "--segment-index": index } as React.CSSProperties} />; })}
      <rect className="signal-sheen" x="-90" y="1" width="90" height="20" rx="8" fill="url(#signal-glow)" />
    </svg>
    <div className="signal-labels"><span>Monitor</span><span>Detect</span><span>Investigate</span><span>Understand</span></div>
  </div>;
}

function Landing({ onSignIn }: { onSignIn: () => void }) { return <div className="landing light-landing"><header className="landing-nav light-landing-nav"><a className="logo-link" href="/" aria-label="SignalGrid home"><SignalGridLogo /></a><a className="landing-signin-button" href="/signin" onClick={event => { event.preventDefault(); onSignIn(); }}>Sign In <span aria-hidden="true">→</span></a></header><main className="light-landing-main"><section className="light-hero-copy"><h1><span>Every Report.</span><span>Every Risk.</span><span className="light-hero-accent">In View.</span></h1><p>One clear workspace for report health, alerts, investigations, and costs.</p></section><SignalTimeline /></main></div>; }
function SignIn({ error, login, back, demoAuthEnabled }: { error: string; login: (username: string, password: string) => Promise<void>; back: () => void; demoAuthEnabled: boolean }) { const [username, setUsername] = useState("admin"); const [password, setPassword] = useState(""); const [showPassword, setShowPassword] = useState(false); const [submitting, setSubmitting] = useState(false); const submit = async (event: FormEvent) => { event.preventDefault(); setSubmitting(true); try { await login(username, password); } finally { setSubmitting(false); } }; return <div className="signin-page light-signin-page"><header className="signin-header light-signin-header"><a className="logo-link" href="/" onClick={event => { event.preventDefault(); back(); }} aria-label="Back to SignalGrid home"><SignalGridLogo /></a></header><main className="light-signin-main"><section className="signin-mission"><span className="light-eyebrow">SIGNALGRID WORKSPACE</span><h1><span>Every Report.</span><span>Every Risk.</span><span className="light-hero-accent">In View.</span></h1><p>One clear workspace for report health, alerts, investigations, and costs.</p><SignalTimeline compact /></section><section className="signin-card light-signin-card" aria-labelledby="signin-heading"><a className="back-home" href="/" onClick={event => { event.preventDefault(); back(); }}>← Back to home</a><h2 id="signin-heading">Welcome to SignalGrid</h2><p className="signin-subtitle">Sign in to access your workspace.</p><form className="signin-form" onSubmit={submit}><label htmlFor="username">Username</label><input id="username" name="username" autoComplete="username" value={username} onChange={event => setUsername(event.target.value)} placeholder="Enter your username" required /><label htmlFor="password">Password</label><div className="password-field"><input id="password" name="password" autoComplete="current-password" type={showPassword ? "text" : "password"} value={password} onChange={event => setPassword(event.target.value)} placeholder="Enter your password" required /><button className="password-toggle" type="button" onClick={() => setShowPassword(value => !value)} aria-label={showPassword ? "Hide password" : "Show password"}>{showPassword ? "Hide" : "Show"}</button></div>{error && <p className="signin-error" role="alert">{error}</p>}<button className="landing-signin-button landing-signin-button--submit" type="submit" disabled={submitting}>{submitting ? <><span className="button-spinner" /> Signing in…</> : <>Sign In <span aria-hidden="true">→</span></>}</button></form>{demoAuthEnabled && <div className="demo-accounts"><strong>Demonstration access</strong><span>Administrator: <code>admin</code> / <code>admin123</code></span><span>Owner (demo user): <code>user</code> / <code>user123</code></span><span>Analyst: <code>analyst</code> / <code>analyst123</code></span></div>}</section></main></div>; }

function AdminChoose({ token, onReplay, onAdminView }: { token: string; onReplay: () => Promise<void>; onAdminView: () => Promise<void> }) {
  const [busy, setBusy] = useState<"replay" | "view" | null>(null); const [error, setError] = useState("");
  const choose = async (kind: "replay" | "view") => { setBusy(kind); setError(""); try { if (kind === "replay") await onReplay(); else await onAdminView(); } catch (nextError) { setError(nextError instanceof Error ? nextError.message : String(nextError)); setBusy(null); } };
  return <div className="admin-entry-page"><header className="admin-entry-header"><a className="logo-link" href="/overview" aria-label="SignalGrid overview"><SignalGridLogo /></a><span className="admin-entry-role"><ShieldCheck size={15} /> Administrator</span></header><main className="admin-entry-main"><section className="admin-entry-card" aria-labelledby="admin-entry-heading"><span className="light-eyebrow">SIGNALGRID WORKSPACE</span><h1 id="admin-entry-heading">Choose your workspace</h1><p>Select a live replay to watch the supplied telemetry move through SignalGrid, or open the completed evaluation immediately.</p><div className="admin-entry-actions"><button className="admin-entry-action admin-entry-action--replay" onClick={() => void choose("replay")} disabled={busy !== null}><span><Play size={18} /> Replay</span><small>Stream all 2,000 observations</small><ChevronRight size={18} /></button><button className="admin-entry-action admin-entry-action--view" onClick={() => void choose("view")} disabled={busy !== null}><span><LayoutDashboard size={18} /> Admin View</span><small>Open completed monitoring state</small><ChevronRight size={18} /></button></div>{busy && <p className="admin-entry-status" role="status"><span className="button-spinner" /> {busy === "replay" ? "Preparing live replay…" : "Preparing completed evaluation…"}</p>}{error && <p className="signin-error" role="alert">{error}</p>}</section></main></div>;
}

function DashboardShell({ page, setPage, token, user, live, liveRevision, streamStatus, logout }: { page: Page; setPage: (page: Page) => void; token: string; user: User; live: LiveEvent[]; liveRevision: number; streamStatus: StreamStatus; logout: () => Promise<void> }) {
  const [collapsed, setCollapsed] = useState(false); const [search, setSearch] = useState(""); const roleLabel = displayRole(user.role); const titles: Record<Page, [string, string]> = { overview: ["Overview", "Operational command centre"], reports: ["Reports", "Report health and ownership"], incidents: ["Alerts", "Actionable incident intelligence"], costs: ["Costs", "Cloud allocation and data quality"] };
  const nav = [{ key: "overview" as Page, label: "Overview", icon: LayoutDashboard }, { key: "reports" as Page, label: "Reports", icon: FileSearch }, { key: "incidents" as Page, label: "Alerts", icon: AlertTriangle }, { key: "costs" as Page, label: "Costs", icon: CircleDollarSign }];
  return <div className={"dashboard-shell " + (collapsed ? "sidebar-collapsed" : "")}><aside className="dashboard-sidebar"><div className="sidebar-brand"><SignalGridLogo compact={collapsed} /><button className="sidebar-toggle" onClick={() => setCollapsed(value => !value)} aria-label={collapsed ? "Expand sidebar" : "Collapse sidebar"}>{collapsed ? <ChevronRight size={16} /> : <ChevronLeft size={16} />}</button></div><nav className="dashboard-nav" aria-label="Main navigation">{nav.map(item => <button className={page === item.key ? "active" : ""} onClick={() => setPage(item.key)} key={item.key} title={item.label}><item.icon size={17} /><span>{item.label}</span>{item.key === "incidents" && live.some(event => event.type === "incident.detected") && <i className="nav-badge" />}</button>)}</nav><div className="sidebar-bottom"><div className="simulation-pill"><span className={"stream-dot stream-" + streamStatus} /><span>Simulated telemetry</span></div><div className="sidebar-user"><div className="avatar"><UserRound size={15} /></div><div><strong>{user.username}</strong><span>{roleLabel}</span></div></div><button className="sidebar-logout" onClick={() => void logout()}>Sign out</button></div></aside><main className="dashboard-main"><header className="dashboard-toolbar"><div className="toolbar-search"><Search size={17} /><input value={search} onChange={event => setSearch(event.target.value)} placeholder="Search reports, incidents…" aria-label="Search dashboard" /><kbd><Command size={12} /> K</kbd></div><div className="toolbar-actions"><span className={"connection-status " + streamStatus}><span className="stream-dot" /> {streamLabel(streamStatus)}</span><span className="role-chip"><ShieldCheck size={14} /> {roleLabel}</span><button className="toolbar-icon" aria-label="Notifications"><Bell size={18} /><i /></button><div className="toolbar-avatar"><UserRound size={17} /></div></div></header><div className="dashboard-content"><div className="page-heading"><div><span className="breadcrumb">SIGNALGRID / {titles[page][0].toUpperCase()}</span><h1>{titles[page][0]}</h1><p>{titles[page][1]}</p></div><span className="simulated-badge"><Activity size={14} /> Simulated telemetry</span></div>{page === "overview" && <Overview token={token} setPage={setPage} live={live} liveRevision={liveRevision} user={user} />}{page === "reports" && <Reports token={token} liveRevision={liveRevision} setPage={setPage} />}{page === "incidents" && <Incidents token={token} user={user} liveRevision={liveRevision} />}{page === "costs" && <Costs token={token} liveRevision={liveRevision} />}</div></main></div>;
}

function DashboardShellModern({ page, setPage, token, user, live, liveRevision, streamStatus, logout, autoStartReplay, onReplayStarted }: { page: Page; setPage: (page: Page) => void; token: string; user: User; live: LiveEvent[]; liveRevision: number; streamStatus: StreamStatus; logout: () => Promise<void>; autoStartReplay: boolean; onReplayStarted: () => void }) {
  const [search, setSearch] = useState(""); const [searchOpen, setSearchOpen] = useState(false); const [searchReports, setSearchReports] = useState<any[]>([]); const [searchIncidents, setSearchIncidents] = useState<any[]>([]); const [notificationsOpen, setNotificationsOpen] = useState(false); const [rcaStatusOpen, setRcaStatusOpen] = useState(false); const [persistedNotifications, setPersistedNotifications] = useState<LiveEvent[]>([]); const [profileOpen, setProfileOpen] = useState(false); const [dismissedToastIds, setDismissedToastIds] = useState<number[]>([]); const [dismissedNotificationKeys, setDismissedNotificationKeys] = useState<string[]>([]); const [dismissedRcaKeys, setDismissedRcaKeys] = useState<string[]>([]); const [selectedIncident, setSelectedIncident] = useState<any>(null); const [selectedReportTarget, setSelectedReportTarget] = useState<string | null>(null); const roleLabel = displayRole(user.role);
  const titles: Record<Page, [string, string]> = { overview: ["Overview", "Source-backed operational health"], reports: ["Reports", "Report health and ownership"], incidents: ["Alerts", "Actionable incident intelligence"], costs: ["Costs", "Cloud allocation and data quality"] };
  useEffect(() => { const query = search.trim(); if (query.length < 2) { setSearchReports([]); setSearchIncidents([]); return; } let cancelled = false; Promise.all([request("/api/reports?page=1&pageSize=6&search=" + encodeURIComponent(query), {}, token), request("/api/incidents?limit=6&search=" + encodeURIComponent(query), {}, token)]).then(([reports, incidents]) => { if (!cancelled) { setSearchReports(reports.data ?? []); setSearchIncidents(incidents.data ?? []); } }).catch(() => { if (!cancelled) { setSearchReports([]); setSearchIncidents([]); } }); return () => { cancelled = true; }; }, [search, token]);
  useEffect(() => { const close = (event: KeyboardEvent) => { if (event.key === "Escape") { setSearchOpen(false); setNotificationsOpen(false); setRcaStatusOpen(false); setProfileOpen(false); } if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "k") { event.preventDefault(); const input = document.querySelector<HTMLInputElement>(".global-search input"); input?.focus(); setSearchOpen(true); } }; window.addEventListener("keydown", close); return () => window.removeEventListener("keydown", close); }, []);
  useEffect(() => { let cancelled = false; request("/api/notifications?limit=60", {}, token).then(data => { if (!cancelled) setPersistedNotifications((data.data ?? []).map((event: any) => ({ type: event.type, eventId: event.eventId ?? event.id, receivedAt: event.timestamp ? Date.parse(event.timestamp) : Date.now(), ...event.payload }))); }).catch(() => undefined); return () => { cancelled = true; }; }, [token, notificationsOpen]);
  const go = (next: Page) => { if (user.role === "ANALYST" && next === "costs") return; setSearchOpen(false); setSearch(""); setPage(next); };
  const eventKey = (event: LiveEvent) => String(event.eventId ?? `${event.type}:${event.reportId ?? event.incident?.reportId ?? ""}:${event.receivedAt}`);
  const notifications = [...live, ...persistedNotifications.filter(event => !live.some(liveEvent => eventKey(liveEvent) === eventKey(event)))].sort((left, right) => right.receivedAt - left.receivedAt); const notificationEvents = notifications.filter(event => ["incident.detected", "incident.updated", "rca.queued", "rca.running", "rca.completed", "rca.fallback", "replay.started", "replay.completed"].includes(event.type)); const visibleNotificationEvents = notificationEvents.filter(event => !dismissedNotificationKeys.includes(eventKey(event))); const notificationCount = visibleNotificationEvents.length; const rcaEvents = notifications.filter(event => ["rca.queued", "rca.completed", "rca.fallback", "rca.running"].includes(event.type)).filter(event => !dismissedRcaKeys.includes(eventKey(event))); const latestRca = rcaEvents[0]; const toastEvents = live.filter(event => ["incident.detected", "incident.updated"].includes(event.type) && !dismissedToastIds.includes(Number(event.eventId))).slice(0, 3);
  const openIncident = (event: LiveEvent) => { const incident = event.incident ?? event; setSelectedIncident({ ...incident, groupId: event.groupId ?? incident.groupId, id: event.incidentId ?? incident.id, reportId: event.reportId ?? incident.reportId, ruleCode: event.ruleCode ?? incident.ruleCode, severity: event.severity ?? incident.severity }); };
  const openReport = (event: LiveEvent) => { const reportId = String(event.incident?.reportId ?? event.reportId ?? ""); if (!reportId) return; setSelectedIncident(null); setNotificationsOpen(false); setRcaStatusOpen(false); setSelectedReportTarget(reportId); go("reports"); };
  const openNotification = (event: LiveEvent) => { if (event.groupId || event.incident?.groupId) { setNotificationsOpen(false); setRcaStatusOpen(false); openIncident(event); } else openReport(event); };
  const dismissToast = (event: LiveEvent) => setDismissedToastIds(ids => [...ids, Number(event.eventId)]);
  const dismissNotification = (event: LiveEvent) => setDismissedNotificationKeys(keys => keys.includes(eventKey(event)) ? keys : [...keys, eventKey(event)]);
  const dismissRca = (event: LiveEvent) => setDismissedRcaKeys(keys => keys.includes(eventKey(event)) ? keys : [...keys, eventKey(event)]);
  return <div className="dashboard-shell dashboard-shell--topnav"><header className="top-navigation"><a className="top-brand" href="/overview" onClick={event => { event.preventDefault(); go("overview"); }} aria-label="SignalGrid overview"><SignalGridLogo /></a><nav className="top-nav-links" aria-label="Primary navigation">{([{ key: "overview", label: "Overview" }, { key: "reports", label: "Reports" }, { key: "incidents", label: "Alerts" }, ...(user.role === "ANALYST" ? [] : [{ key: "costs", label: "Costs" }])] as Array<{ key: Page; label: string }>).map(item => <button key={item.key} className={page === item.key ? "active" : ""} onClick={() => go(item.key)}>{item.label}</button>)}</nav><div className="top-nav-actions"><div className={"global-search " + (searchOpen ? "is-open" : "")}><Search size={16} /><input value={search} onFocus={() => setSearchOpen(true)} onChange={event => { setSearch(event.target.value); setSearchOpen(true); }} placeholder="Search reports, alerts…" aria-label="Search reports and alerts" /><kbd><Command size={11} /> K</kbd>{searchOpen && search.trim().length >= 2 && <div className="search-popover"><div className="search-popover-header">Search results</div>{searchReports.length === 0 && searchIncidents.length === 0 && <p className="search-empty">No matching reports or alerts.</p>}{searchReports.map(report => <button key={report.reportId} onClick={() => { setSelectedReportTarget(report.reportId); go("reports"); }}><span className="search-result-mark report-mark"><FileSearch size={14} /></span><span><strong>{report.reportId}</strong><small>{report.reportName} · {fmt(report.maxLatencySec)}s peak</small></span><ChevronRight size={14} /></button>)}{searchIncidents.map(incident => <button key={incident.id} onClick={() => { setSearchOpen(false); setSelectedIncident({ ...incident, groupId: incident.groupId ?? incident.id }); go("incidents"); }}><span className="search-result-mark alert-mark"><AlertTriangle size={14} /></span><span><strong>{incident.reportId}</strong><small>{incident.ruleCode.replaceAll("_", " ")} · {incident.severity}</small></span><ChevronRight size={14} /></button>)}</div>}</div><div className="nav-popover-wrap"><button className="nav-icon-button" aria-label="RCA status" onClick={() => { setRcaStatusOpen(value => !value); setNotificationsOpen(false); setProfileOpen(false); }}><Clock3 size={18} />{rcaEvents.length > 0 && <i className={latestRca?.type === "rca.fallback" ? "status-dot status-dot--warning" : ""} />}</button>{rcaStatusOpen && <div className="nav-popover rca-status-popover"><div className="nav-popover-header"><span>RCA status</span><small>{latestRca ? displayStatus(latestRca.type.replace("rca.", "")) : "No requests"}</small></div>{latestRca ? <div className="rca-status-card"><div className="rca-status-card-top"><strong>{latestRca.reportId ?? "Incident investigation"}</strong><button className="rca-status-dismiss" onClick={() => dismissRca(latestRca)} aria-label="Dismiss RCA status"><X size={13} /></button></div><span>{latestRca.type === "rca.running" ? "Analysis in progress…" : latestRca.type === "rca.fallback" ? "RCA unavailable right now. Please try again later." : latestRca.type === "rca.queued" ? "Investigation queued." : "Explainable analysis ready for review."}</span>{latestRca.type === "rca.completed" && latestRca.result?.summary && <p>{String(latestRca.result.summary)}</p>}</div> : <p className="search-empty">Request RCA from an alert or report record.</p>}</div>}</div><div className="nav-popover-wrap"><button className="nav-icon-button" aria-label="Notifications" onClick={() => { setNotificationsOpen(value => !value); setRcaStatusOpen(false); setProfileOpen(false); }}><Bell size={18} />{notificationCount > 0 && <i />}</button>{notificationsOpen && <div className="nav-popover notification-popover"><div className="nav-popover-header"><span>Notifications</span><small>{notificationCount} recent</small></div>{visibleNotificationEvents.slice(0, 6).map((event, index) => { const reportId = event.incident?.reportId ?? event.reportId; return <div className="notification-row" key={eventKey(event) + index}><button className="notification-row-main" onClick={() => reportId ? openNotification(event) : setNotificationsOpen(false)} aria-label={reportId ? `Open ${reportId} in Reports` : notificationTitle(event)}><span className="notification-dot" /><span><strong>{notificationTitle(event)}</strong><small>{notificationMeta(event)}</small></span></button><button className="notification-row-action" onClick={() => dismissNotification(event)} aria-label="Dismiss notification"><X size={13} /></button>{reportId && <button className="notification-row-action" onClick={() => openNotification(event)} aria-label={`Investigate ${reportId}`}><Search size={13} /></button>}</div>; })}{notificationCount === 0 && <p className="search-empty">No new authorized events.</p>}</div>}</div><div className="nav-popover-wrap"><button className="profile-button" aria-label="Open profile menu" onClick={() => { setProfileOpen(value => !value); setNotificationsOpen(false); setRcaStatusOpen(false); }}><span className="profile-avatar"><UserRound size={16} /></span><span className="profile-copy"><strong>{user.username}</strong><small>{roleLabel}</small></span><ChevronRight size={14} className={profileOpen ? "profile-chevron profile-chevron--open" : "profile-chevron"} /></button>{profileOpen && <div className="nav-popover profile-popover"><div className="profile-popover-heading"><span className="profile-avatar profile-avatar--large"><UserRound size={18} /></span><span><strong>{user.username}</strong><small>{roleLabel}</small></span></div><button className="profile-signout" onClick={() => void logout()}>Sign out</button></div>}</div></div></header><main className="dashboard-main dashboard-main--topnav"><div className="dashboard-content">{page !== "overview" && <div className="page-heading"><div><span className="breadcrumb">SIGNALGRID / {titles[page][0].toUpperCase()}</span><h1>{titles[page][0]}</h1><p>{titles[page][1]}</p></div><span className="simulated-badge"><Activity size={14} /> Simulated telemetry</span></div>}{page === "overview" && <Overview token={token} setPage={go} live={live} liveRevision={liveRevision} user={user} autoStartReplay={autoStartReplay} onReplayStarted={onReplayStarted} streamStatus={streamStatus} />}{page === "reports" && <Reports token={token} liveRevision={liveRevision} setPage={go} reportTarget={selectedReportTarget} onReportTargetHandled={() => setSelectedReportTarget(null)} />}{page === "incidents" && <Incidents token={token} user={user} liveRevision={liveRevision} />}{page === "costs" && <Costs token={token} liveRevision={liveRevision} />}</div></main>{toastEvents.length > 0 && <div className="replay-toast-stack" aria-live="polite">{toastEvents.map(event => <article className="replay-toast" key={String(event.eventId)}><div className="replay-toast-top"><span className="notification-dot" /><div><strong>{notificationTitle(event)}</strong><small>{notificationMeta(event)}</small></div><button className="toast-close" onClick={() => dismissToast(event)} aria-label="Dismiss notification"><X size={15} /></button></div><p>{notificationDetail(event)}</p><div className="toast-actions"><button className="toast-investigate" onClick={() => openIncident(event)}><Search size={13} /> Investigate</button></div></article>)}</div>}{selectedIncident && <InvestigationDrawer token={token} user={user} row={selectedIncident} liveRevision={liveRevision} close={() => setSelectedIncident(null)} refresh={() => undefined} />}</div>;
}

function MetricCard({ label, value, detail, icon: Icon, tone = "teal" }: { label: string; value: unknown; detail: string; icon: typeof Activity; tone?: string }) { return <article className={"metric-card glass-panel " + tone}><div className="metric-top"><span>{label}</span><span className="metric-icon"><Icon size={17} /></span></div><strong>{fmt(value, 0)}</strong><small>{detail}</small></article>; }

function ReplaySelect({ label, value, options, onChange }: { label: string; value: string; options: Array<{ value: string; label: string }>; onChange: (value: string) => void }) {
  const [open, setOpen] = useState(false);
  const rootRef = useRef<HTMLDivElement>(null);
  const selected = options.find(option => option.value === value) ?? options[0];
  useEffect(() => {
    const close = (event: MouseEvent) => { if (rootRef.current && !rootRef.current.contains(event.target as globalThis.Node)) setOpen(false); };
    document.addEventListener("mousedown", close);
    return () => document.removeEventListener("mousedown", close);
  }, []);
  const choose = (nextValue: string) => { onChange(nextValue); setOpen(false); };
  return <div className="replay-field" ref={rootRef}>
    <span className="replay-field-label">{label}</span>
    <div className="replay-select">
      <button type="button" className="replay-select-trigger" aria-label={`${label}: ${selected?.label ?? ""}`} aria-haspopup="listbox" aria-expanded={open} onClick={() => setOpen(current => !current)} onKeyDown={event => {
        if (event.key === "Escape") setOpen(false);
        if (event.key === "ArrowDown" || event.key === "ArrowUp" || event.key === "Enter" || event.key === " ") { event.preventDefault(); setOpen(true); }
      }}>
        <span>{selected?.label}</span><ChevronDown size={15} aria-hidden="true" />
      </button>
      {open && <div className="replay-select-menu" role="listbox" aria-label={label}>
        {options.map(option => <button type="button" role="option" aria-selected={option.value === value} className={option.value === value ? "is-selected" : ""} key={option.value} onClick={() => choose(option.value)}>{option.label}</button>)}
      </div>}
    </div>
  </div>;
}

function ReplayControls({ token, user, compact = false, autoStart = false, onReplayStarted, streamStatus }: { token: string; user: User; compact?: boolean; autoStart?: boolean; onReplayStarted?: () => void; streamStatus?: StreamStatus }) {
  const [session, setSession] = useState<any>(null); const [mode, setMode] = useState("full"); const [speed, setSpeed] = useState("5"); const [message, setMessage] = useState(""); const autoStarted = useRef(false);
  const refresh = () => request("/api/replay/status", {}, token).then(data => setSession(data.session)).catch(() => undefined);
  useEffect(() => { void refresh(); const timer = window.setInterval(refresh, 1200); return () => window.clearInterval(timer); }, [token]);
  const scoped = user.role !== "ADMIN";
  const scopedPath = (path: string) => scoped ? ({ "/api/replay/pause": "/api/replay/scoped/pause", "/api/replay/resume": "/api/replay/scoped/resume", "/api/replay/step": "/api/replay/scoped/step" } as Record<string, string>)[path] ?? path : path;
  const call = async (path: string, body?: any) => { try { const payload = scoped ? { ...(body ?? {}), sessionId: body?.sessionId ?? session?.id } : body; const data = await request(scopedPath(path), { method: "POST", body: payload ? JSON.stringify(payload) : undefined }, token); setSession(data.session); setMessage(""); return data; } catch (error) { setMessage(error instanceof Error ? error.message : String(error)); return undefined; } };
  useEffect(() => { if (!autoStart || user.role !== "ADMIN" || streamStatus !== "connected" || !session || session.state !== "configured" || autoStarted.current) return; autoStarted.current = true; void call("/api/replay/start").then(result => { if (result) onReplayStarted?.(); }); }, [autoStart, streamStatus, session?.id, session?.state, user.role]);
  const start = async () => { try { if (scoped) { const configured = await request("/api/replay/scoped/config", { method: "POST", body: JSON.stringify({ mode, speed: Number(speed), seed: 42, ordering: "sequential" }) }, token); setSession(configured.session); await request("/api/replay/scoped/start", { method: "POST", body: JSON.stringify({ sessionId: configured.session.id }) }, token); return; } if (mode === "curated") { const prepared = await request("/api/demo/prepare", { method: "POST", body: JSON.stringify({ seed: 42, speed: Number(speed) }) }, token); setSession(prepared.session); await request("/api/demo/start", { method: "POST", body: JSON.stringify({ sessionId: prepared.session.id, cursor: prepared.cursor }) }, token); } else { const configured = await call("/api/replay/config", { mode: "full", speed: Number(speed), seed: 42, ordering: "sequential" }); if (configured) await call("/api/replay/start"); } } catch (error) { setMessage(error instanceof Error ? error.message : String(error)); } };
  const restart = async () => { try { if (scoped) { const configured = await request("/api/replay/scoped/config", { method: "POST", body: JSON.stringify({ mode, speed: Number(speed), seed: 42, ordering: "sequential" }) }, token); setSession(configured.session); await request("/api/replay/scoped/start", { method: "POST", body: JSON.stringify({ sessionId: configured.session.id }) }, token); return; } if (mode === "full") { await call("/api/replay/restart", { start: true }); } else { const prepared = await request("/api/demo/restart", { method: "POST", body: JSON.stringify({ seed: 42, speed: Number(speed) }) }, token); setSession(prepared.session); await request("/api/demo/start", { method: "POST", body: JSON.stringify({ sessionId: prepared.session.id, cursor: prepared.cursor }) }, token); } } catch (error) { setMessage(error instanceof Error ? error.message : String(error)); } };
  const roleLabel = scoped ? `${displayRole(user.role)} scoped replay` : undefined;
  const position = session?.position ?? 0; const total = session?.total ?? 0; const pct = total ? Math.round((position / total) * 100) : 0; const label = session?.state === "completed" ? "Completed evaluation" : scoped ? roleLabel : mode === "full" ? "Full live replay" : "Curated replay";
  return <section className={"replay-panel glass-panel " + (compact ? "replay-panel-compact" : "")}><div className="replay-heading"><div><span className="eyebrow">SIMULATED TELEMETRY</span><h3>Telemetry Replay</h3><small className="replay-mode-label">{label}</small></div><span className={"state-chip " + (session?.state ?? "idle")}>{displayStatus(session?.state ?? "idle")}</span></div><div className="replay-controls-row"><div className="replay-progress"><div><span>Progress</span><strong>{position.toLocaleString()} / {total.toLocaleString()} · {pct}%</strong></div><div className="progress-track"><i style={{ width: pct + "%" }} /></div></div><ReplaySelect label="Mode" value={mode} onChange={setMode} options={[{ value: "curated", label: "Curated Demo" }, { value: "full", label: "Full Dataset" }]} /><ReplaySelect label="Speed" value={speed} onChange={setSpeed} options={[{ value: "1", label: "1×" }, { value: "5", label: "5×" }, { value: "20", label: "20×" }]} /><div className="replay-buttons"><button className="primary-action" onClick={() => void start()} disabled={session?.state === "running"}><Play size={14} /> Start</button><button onClick={() => void call("/api/replay/pause")} disabled={session?.state !== "running"}><Pause size={14} /> Pause</button><button onClick={() => void call("/api/replay/resume")} disabled={session?.state !== "paused"}><Play size={14} /> Resume</button><button onClick={() => void call("/api/replay/step")} disabled={session?.state === "running"}><StepForward size={14} /> Step</button><button onClick={() => void restart()}><RefreshCw size={14} /> Restart</button></div></div>{message && <p className="inline-error">{message}</p>}</section>;
}

type FlowData = { label: string; count: number; color: string; icon: typeof Activity; reportId?: string; report?: any };
function FlowCategoryNode({ data }: { data: FlowData }) { return <div className="flow-category-node" style={{ "--node-accent": data.color } as any}><Handle type="source" position={Position.Bottom} /><div className="flow-node-icon"><data.icon size={16} /></div><div><strong>{data.label}</strong><span>{data.count} reports</span></div><MoreHorizontal size={16} /></div>; }
function FlowReportNode({ data }: { data: FlowData }) { return <div className="flow-report-node" style={{ "--node-accent": data.color } as any}><Handle type="target" position={Position.Top} /><strong>{data.reportId}</strong><span>{fmt(data.report?.medianLatencySec)}s median · {data.report?.refreshStatusMode ?? "—"}</span></div>; }
function HealthMap({ categories, onReport }: { categories: Array<FlowData & { key: string; reports: any[] }>; onReport: (report: any) => void }) {
  const [mode, setMode] = useState<"map" | "list">("map"); const [expanded, setExpanded] = useState<string | null>(null);
  const nodes = useMemo(() => { const base: Node<FlowData>[] = categories.map((category, index) => ({ id: category.key, type: "category", position: { x: 26 + (index % 2) * 300, y: 26 + Math.floor(index / 2) * 130 }, data: category })); if (!expanded) return base; const category = categories.find(item => item.key === expanded); if (!category) return base; return base.concat(category.reports.slice(0, 6).map((report, index) => ({ id: expanded + "-" + report.reportId, type: "report", position: { x: 42 + index * 160, y: 300 }, data: { label: report.reportId, reportId: report.reportId, report: report, count: 1, color: category.color, icon: category.icon } }))); }, [categories, expanded]);
  const edges: Edge[] = expanded ? (categories.find(item => item.key === expanded)?.reports.slice(0, 6).map(report => ({ id: expanded + "-" + report.reportId + "-edge", source: expanded, target: expanded + "-" + report.reportId, animated: true, style: { stroke: categories.find(item => item.key === expanded)?.color } })) ?? []) : [];
  return <section className="health-map glass-panel"><div className="panel-header"><div><span className="eyebrow">REPORT HEALTH MAP</span><h2>God’s View</h2><p>Grouped from live source-backed rules, with drill-down to report evidence.</p></div><div className="map-tools"><button className={mode === "map" ? "active" : ""} onClick={() => setMode("map")}><Map size={14} /> Map</button><button className={mode === "list" ? "active" : ""} onClick={() => setMode("list")}><List size={14} /> List</button></div></div>{mode === "map" ? <div className="flow-canvas"><ReactFlow nodes={nodes} edges={edges} nodeTypes={{ category: FlowCategoryNode, report: FlowReportNode }} fitView fitViewOptions={{ padding: 0.15 }} nodesDraggable={false} onNodeClick={(_event: unknown, node: Node) => { if (node.type === "category") setExpanded(expanded === node.id ? null : node.id); else { const report = (node.data as FlowData).report; if (report) onReport(report); } }}><Background color="#d9e8e4" gap={22} /><Controls showInteractive={false} /></ReactFlow>{expanded && <button className="flow-reset" onClick={() => setExpanded(null)}>Collapse report drill-down</button>}</div> : <div className="health-list">{categories.map(category => <div className="health-list-group" key={category.key}><button onClick={() => setExpanded(expanded === category.key ? null : category.key)}><span className="health-list-icon" style={{ background: category.color + "18", color: category.color }}><category.icon size={17} /></span><span><strong>{category.label}</strong><small>{category.reports.length} reports need review</small></span><b>{category.count}</b>{expanded === category.key ? <ChevronLeft size={16} /> : <ChevronRight size={16} />}</button>{expanded === category.key && <div className="health-list-reports">{category.reports.slice(0, 6).map(report => <button onClick={() => onReport(report)} key={report.reportId}><span>{report.reportId}</span><small>{fmt(report.medianLatencySec)}s median</small><ChevronRight size={14} /></button>)}</div>}</div>)}</div>}</section>;
}

function OverviewLegacy({ token, setPage, live, liveRevision, user }: { token: string; setPage: (page: Page) => void; live: LiveEvent[]; liveRevision: number; user: User }) {
  const [data, setData] = useState<any>(); const [analytics, setAnalytics] = useState<any>(); const [costs, setCosts] = useState<any>(); const [reports, setReports] = useState<any[]>([]); const [selectedReport, setSelectedReport] = useState<any>(null);
  useEffect(() => { let cancelled = false; const refresh = () => Promise.all([request("/api/overview", {}, token), request("/api/analytics", {}, token), request("/api/costs", {}, token), request("/api/reports?page=1&pageSize=100", {}, token)]).then(([overview, nextAnalytics, nextCosts, nextReports]) => { if (!cancelled) { setData(overview); setAnalytics(nextAnalytics); setCosts(nextCosts); setReports(nextReports.data ?? []); } }).catch(() => undefined); void refresh(); const timer = window.setInterval(refresh, 2600); return () => { cancelled = true; window.clearInterval(timer); }; }, [token, liveRevision]);
  if (!data || !analytics || !costs) return <Loading />;
  const categories = buildCategories(reports, new Set((costs.costUsageQuality?.flaggedReports ?? []).map((item: any) => item.reportId))); const reviewCount = new Set(categories.flatMap(category => category.reports.map(report => report.reportId))).size; const flagged = costs.costUsageQuality?.flaggedReports?.length ?? 0;
  return <><div className="metric-grid"><MetricCard label="Reports monitored" value={data.reports} detail={fmt(data.observations, 0) + " source observations"} icon={Database} /><MetricCard label="Reports needing review" value={reviewCount} detail="Grouped by deterministic rule" icon={AlertTriangle} tone="orange" /><MetricCard label="Current replay alerts" value={data.groupedIncidents} detail={fmt(data.detectionEvents ?? data.observations, 0) + " detections preserved"} icon={Zap} tone="violet" /><MetricCard label="Cost / data-quality flags" value={flagged + (data.invalidCredits ?? 0)} detail={flagged + " AWS outlier reviews · " + (data.invalidCredits ?? 0) + " invalid credits"} icon={CircleDollarSign} tone="red" /></div><ReplayControls token={token} user={user} compact /><div className="overview-grid"><HealthMap categories={categories} onReport={setSelectedReport} /><section className="attention-card glass-panel"><div className="panel-header"><div><span className="eyebrow">LIVE QUEUE</span><h2>What needs attention</h2></div><button className="link-button" onClick={() => setPage("incidents")}>View all <ChevronRight size={15} /></button></div><div className="attention-list">{categories.map(category => <button className="attention-row" key={category.key} onClick={() => setPage(category.key === "costs" ? "costs" : "incidents")}><span className="attention-icon" style={{ color: category.color, background: category.color + "16" }}><category.icon size={16} /></span><span><strong>{category.label}</strong><small>{category.reports.length} reports · source-backed</small></span><b>{category.count}</b><ChevronRight size={15} /></button>)}</div><div className="attention-footer"><span><span className="stream-dot stream-connected" /> Events are live</span><span>{data.quality?.length ?? 0} data-quality categories</span></div></section><section className="review-card glass-panel"><div className="panel-header"><div><span className="eyebrow">PRIORITIZED</span><h2>Reports to review</h2></div><button className="icon-button" onClick={() => setPage("reports")} aria-label="Open reports"><ChevronRight size={17} /></button></div><div className="review-list">{analytics.topLatencyReports.slice(0, 5).map((report: any) => <button className="review-row" onClick={() => setSelectedReport(report)} key={report.reportId}><span className="report-avatar">{report.reportId.replace("RPT-", "").slice(-2)}</span><span><strong>{report.reportId}</strong><small>{fmt(report.maxLatencySec)}s peak · {report.refreshStatusMode}</small></span><span className="review-tag">{report.maxLatencySec > 30 ? "High" : "Review"}</span></button>)}</div></section><ActivityPanel live={live} analytics={analytics} /><section className="chart-card glass-panel"><div className="panel-header"><div><span className="eyebrow">OBSERVATION LATENCY</span><h2>Refresh health</h2></div><Gauge size={18} className="panel-icon" /></div><div className="chart-wrap small-chart"><ResponsiveContainer width="100%" height="100%"><BarChart data={analytics.latencyDistribution}><CartesianGrid vertical={false} stroke="#e5efec" /><XAxis dataKey="bucket" axisLine={false} tickLine={false} tick={{ fill: "#7a918c", fontSize: 11 }} /><YAxis axisLine={false} tickLine={false} tick={{ fill: "#7a918c", fontSize: 11 }} /><Tooltip cursor={{ fill: "#eff8f5" }} /><Bar dataKey="count" radius={[6, 6, 0, 0]}>{analytics.latencyDistribution.map((_: any, index: number) => <Cell key={index} fill={["#56b7a5", "#7ecbbb", "#f5a35d", "#de6258"][index]} />)}</Bar></BarChart></ResponsiveContainer></div><div className="refresh-legend">{analytics.refreshHealth.map((item: any) => <span key={item.status}><i className={"dot-" + item.status.toLowerCase()} /> {item.status.replace("_", " ")} <b>{item.count}</b></span>)}</div></section></div>{selectedReport && <ReportInspector token={token} report={selectedReport} close={() => setSelectedReport(null)} setPage={setPage} />}</>;
}
function buildCategories(reports: any[], flaggedCostReports: Set<string>) { const groups = [{ key: "slow", label: "Slow Loads", color: "#e98a40", icon: Gauge, test: (row: any) => row.maxLatencySec > 15 }, { key: "refresh", label: "Refresh Issues", color: "#dd625c", icon: RefreshCw, test: (row: any) => ["FAILED", "TIMED_OUT", "UNKNOWN"].some(status => (row.refreshStatusCounts ?? {})[status]) }, { key: "owners", label: "Missing Owners", color: "#8a6bd4", icon: UserRound, test: (row: any) => row.orphanedObservations > 0 }, { key: "costs", label: "High Costs", color: "#2f9f95", icon: CircleDollarSign, test: (row: any) => flaggedCostReports.has(row.reportId) }]; return groups.map(group => { const matching = reports.filter(group.test); return { ...group, count: matching.length, reports: matching }; }); }
function ActivityPanel({ live, analytics }: { live: LiveEvent[]; analytics: any }) { const events = live.length ? live : (analytics.replayEvents ?? []).slice(0, 8).map((item: any, index: number) => ({ type: item.type, eventId: index, receivedAt: Date.parse(item.timestamp), ...item.payload })); return <section className="activity-card glass-panel"><div className="panel-header"><div><span className="eyebrow">REAL-TIME EVENT BUS</span><h2>Live activity</h2></div><span className="live-label"><span className="stream-dot stream-connected" /> Live</span></div>{events.length ? <div className="activity-feed">{events.slice(0, 8).map((event: any, index: number) => <div className="activity-item" key={String(event.eventId) + "-" + index}><span className={"activity-marker " + (event.type.includes("incident") ? "critical" : event.type.includes("rca") ? "violet" : "teal")}><Activity size={13} /></span><div><strong>{event.type.replaceAll(".", " ")}</strong><small>{activityMeta(event)}</small></div><time>{relativeTime(event.receivedAt)}</time></div>)}</div> : <Empty text="Start a curated replay to see observations arrive through SSE." />}</section>; }
function relativeTime(value: number) { if (!value) return "now"; const seconds = Math.max(0, Math.round((Date.now() - value) / 1000)); return seconds < 60 ? seconds + "s" : Math.round(seconds / 60) + "m"; }
function activityMeta(event: any) { const report = event.incident?.reportId ?? event.reportId ?? event.observationId ?? "Incident " + (event.incidentId ?? ""); const rule = event.incident?.ruleCode ?? event.ruleCode; return report + (rule ? " · " + rule : "") + (event.simulationTimestamp ? " · " + String(event.simulationTimestamp).slice(11, 19) : ""); }
function notificationTitle(event: any) { const report = event.incident?.reportId ?? event.reportId ?? "Incident"; const rule = event.incident?.ruleCode ?? event.ruleCode ?? (event.type === "rca.completed" ? "RCA complete" : event.type.replaceAll(".", " ")); return `${report} · ${String(rule).replaceAll("_", " ")}`; }
function notificationMeta(event: any) { const severity = event.incident?.severity ?? event.severity; const state = event.type === "rca.completed" ? (event.result?.generatedBy === "ai" && event.result?.validationOutcome === "verified" ? "AI investigation ready" : "Source-backed analysis available") : event.type === "rca.fallback" ? "AI unavailable · source evidence available" : event.type === "rca.running" ? "Investigation running" : event.type === "rca.queued" ? "Investigation queued" : displayStatus(event.incident?.status ?? event.status ?? "open"); return [severity ? displayStatus(severity) : null, state].filter(Boolean).join(" · "); }
function notificationDetail(event: any) { const report = event.incident?.reportId ?? event.reportId ?? "This report"; const rule = event.incident?.ruleCode ?? event.ruleCode ?? "source-backed rule"; return `${report} triggered ${String(rule).replaceAll("_", " ")}. Review the preserved evidence before taking action.`; }

function TablePagination({ page, pageSize, total, onPageChange, label }: { page: number; pageSize: number; total: number; onPageChange: (page: number) => void; label: string }) { const pageCount = Math.max(1, Math.ceil(total / pageSize)); const start = total ? (page - 1) * pageSize + 1 : 0; const end = Math.min(total, page * pageSize); const visibleStart = pageCount <= 5 ? 1 : Math.min(Math.max(1, page - 2), pageCount - 4); const visiblePages = Array.from({ length: Math.min(5, pageCount) }, (_, index) => visibleStart + index); return <div className="table-pagination"><span className="table-pagination-summary">Showing {start}–{end} of {total} {label}</span><div className="table-pagination-controls"><button type="button" onClick={() => onPageChange(Math.max(1, page - 1))} disabled={page <= 1} aria-label="Previous page"><ChevronLeft size={15} /></button>{visiblePages.map(number => <button type="button" key={number} className={number === page ? "active" : ""} onClick={() => onPageChange(number)} aria-current={number === page ? "page" : undefined}>{number}</button>)}<button type="button" onClick={() => onPageChange(Math.min(pageCount, page + 1))} disabled={page >= pageCount} aria-label="Next page"><ChevronRight size={15} /></button></div></div>; }
function FilterMenu({ open, onToggle, onClear, activeCount, children }: { open: boolean; onToggle: () => void; onClear: () => void; activeCount: number; children: ReactNode }) { return <div className="filter-menu-wrap"><button className="filter-button" type="button" onClick={onToggle} aria-expanded={open}><SlidersHorizontal size={15} /> Filters {activeCount > 0 && <span className="filter-count">{activeCount}</span>}</button>{open && <div className="filter-menu" role="dialog" aria-label="Table filters"><div className="filter-menu-header"><strong>Filter view</strong><span>Updates the table immediately</span></div><div className="filter-menu-fields">{children}</div><div className="filter-menu-actions"><button type="button" onClick={onClear}>Clear</button><button type="button" className="filter-menu-done" onClick={onToggle}>Done</button></div></div>}</div>; }
function Reports({ token, liveRevision, setPage, reportTarget, onReportTargetHandled }: { token: string; liveRevision: number; setPage: (page: Page) => void; reportTarget?: string | null; onReportTargetHandled?: () => void }) { const [data, setData] = useState<any>(); const [search, setSearch] = useState(""); const [orphaned, setOrphaned] = useState(false); const [ownerFilter, setOwnerFilter] = useState("all"); const [latencyFilter, setLatencyFilter] = useState("all"); const [refreshFilter, setRefreshFilter] = useState("all"); const [filtersOpen, setFiltersOpen] = useState(false); const [selected, setSelected] = useState<any>(null); const [page, setPageNumber] = useState(1); const pageSize = workspacePageSize(); const activeFilterCount = Number(orphaned || ownerFilter !== "all") + Number(latencyFilter !== "all") + Number(refreshFilter !== "all"); useEffect(() => { request("/api/reports?page=" + page + "&pageSize=" + pageSize + "&search=" + encodeURIComponent(search) + "&orphaned=" + orphaned + "&owner=" + encodeURIComponent(ownerFilter) + "&latency=" + encodeURIComponent(latencyFilter) + "&refresh=" + encodeURIComponent(refreshFilter), {}, token).then(setData).catch(() => undefined); }, [token, search, orphaned, ownerFilter, latencyFilter, refreshFilter, page, pageSize, liveRevision]); useEffect(() => { setPageNumber(1); setSelected(null); }, [search, orphaned, ownerFilter, latencyFilter, refreshFilter]); useEffect(() => { if (!reportTarget) return; const exact = data?.data?.find((row: any) => row.reportId === reportTarget); if (exact) { setSelected(exact); onReportTargetHandled?.(); return; } request("/api/reports?page=1&pageSize=100&search=" + encodeURIComponent(reportTarget), {}, token).then(next => { const found = (next.data ?? []).find((row: any) => row.reportId === reportTarget); if (found) setSelected(found); onReportTargetHandled?.(); }).catch(() => onReportTargetHandled?.()); }, [reportTarget, data, token]); const clearFilters = () => { setOrphaned(false); setOwnerFilter("all"); setLatencyFilter("all"); setRefreshFilter("all"); }; return <>{!data ? <Loading /> : <section className="workspace-grid"><section className="table-card glass-panel"><div className="workspace-toolbar"><div><span className="eyebrow">OBSERVATION SUMMARIES</span><h2>Reports</h2><p>{data.total} report identities from preserved source rows.</p></div><div className="filter-bar"><div className="inline-search"><Search size={15} /><input value={search} onChange={event => setSearch(event.target.value)} placeholder="Search reports" /></div><label className="checkbox-label"><input type="checkbox" checked={orphaned || ownerFilter === "missing"} onChange={event => { setOrphaned(event.target.checked); setOwnerFilter("all"); }} /> Missing owner</label><FilterMenu open={filtersOpen} onToggle={() => setFiltersOpen(value => !value)} onClear={clearFilters} activeCount={activeFilterCount}><label>Owner<select value={ownerFilter} onChange={event => { setOwnerFilter(event.target.value); setOrphaned(false); }}><option value="all">All owners</option><option value="assigned">Assigned owners</option><option value="missing">Missing / placeholder</option><option value="conflicting">Conflicting observations</option></select></label><label>Latency<select value={latencyFilter} onChange={event => setLatencyFilter(event.target.value)}><option value="all">All latency</option><option value="slow">Over 15 seconds</option><option value="critical">30 seconds and over</option><option value="healthy">15 seconds or less</option></select></label><label>Refresh state<select value={refreshFilter} onChange={event => setRefreshFilter(event.target.value)}><option value="all">All refresh states</option><option value="SUCCESS">Success present</option><option value="FAILED">Failed present</option><option value="TIMED_OUT">Timed out present</option><option value="UNKNOWN">Unknown present</option></select></label></FilterMenu></div></div><div className="table-scroll"><table><thead><tr><th>Report</th><th>Owner</th><th>Refresh</th><th>Median latency</th><th>Peak latency</th><th>Cost / view</th><th /></tr></thead><tbody>{data.data.map((row: any) => <tr key={row.reportId} onClick={() => setSelected(row)} className={selected?.reportId === row.reportId ? "selected" : ""}><td><strong>{row.reportId}</strong><small>{row.reportName}</small></td><td><span className={row.orphanedObservations ? "warning-text" : ""}>{row.owner}</span><small>{row.observationCount} observations</small></td><td><span className={"status-badge " + String(row.refreshStatusMode).toLowerCase()}>{displayStatus(row.refreshStatusMode)}</span><small>{Object.entries(row.refreshStatusCounts ?? {}).map(([key, value]) => key + ": " + value).join(" · ")}</small></td><td className={row.medianLatencySec > 15 ? "warning-text" : ""}>{fmt(row.medianLatencySec)}s</td><td className={row.maxLatencySec > 15 ? "warning-text" : ""}>{fmt(row.maxLatencySec)}s</td><td>{money(row.medianAwsCostPerActiveViewUsd, 4)}</td><td><ChevronRight size={15} /></td></tr>)}</tbody></table></div><TablePagination page={data.page ?? page} pageSize={data.pageSize ?? pageSize} total={data.total ?? 0} onPageChange={nextPage => { setPageNumber(nextPage); setSelected(null); }} label="reports" /></section>{selected && <ReportInspector token={token} report={selected} close={() => setSelected(null)} setPage={setPage} />}</section>}</>; }
function ReportInspector({ token, report, close, setPage, liveRevision = 0 }: { token: string; report: any; close: () => void; setPage: (page: Page) => void; liveRevision?: number }) { const [detail, setDetail] = useState<any>(report ?? {}); const [ownership, setOwnership] = useState<any>(null); const [loadError, setLoadError] = useState(""); useEffect(() => { let cancelled = false; setLoadError(""); const reportId = encodeURIComponent(String(report?.reportId ?? "")); Promise.all([request("/api/reports/" + reportId, {}, token), request("/api/reports/" + reportId + "/ownership", {}, token)]).then(([next, nextOwnership]) => { if (!cancelled) { setDetail(next); setOwnership(nextOwnership); } }).catch(() => { if (!cancelled) { setDetail(report ?? {}); setLoadError("Unable to load report details. Showing the available summary."); } }); return () => { cancelled = true; }; }, [token, report, liveRevision]); const safeDetail = detail ?? report ?? {}; const observations = Array.isArray(safeDetail.observations) ? safeDetail.observations : []; const incidents = Array.isArray(safeDetail.incidents) ? safeDetail.incidents : []; const firstGroupId = incidents.find((incident: any) => incident?.groupId)?.groupId; const brief = safeDetail.investigationBrief ?? {}; const ownershipStatus = ownership?.notVerifiedCurrentOwner ? "Current owner cannot be verified from supplied records." : "Source ownership recorded."; return <Drawer title={String(safeDetail.reportId ?? report?.reportId ?? "Report")} eyebrow="REPORT INSPECTOR" close={close}><div className="drawer-subtitle">{String(safeDetail.reportName ?? report?.reportName ?? "Source report")}</div>{loadError && <p className="drawer-inline-error" role="status">{loadError}</p>}<div className="drawer-stats"><DrawerStat label="Owner" value={String(safeDetail.owner ?? "—")} /><DrawerStat label="Median latency" value={fmt(safeDetail.medianLatencySec) + "s"} tone={Number(safeDetail.medianLatencySec) > 15 ? "warning" : ""} /><DrawerStat label="Refresh mode" value={displayStatus(safeDetail.refreshStatusMode ?? "—")} /><DrawerStat label="Observations" value={fmt(safeDetail.observationCount, 0)} /></div><section className="drawer-section"><h4>Health signals</h4><div className="signal-grid"><span>Peak latency <b>{fmt(safeDetail.maxLatencySec)}s</b></span><span>Invalid credits <b>{safeDetail.invalidCreditObservations ?? 0}</b></span><span>Zero views <b>{safeDetail.zeroViewObservations ?? 0}</b></span><span>Incidents <b>{incidents.length}</b></span></div></section><section className="drawer-section"><h4>Ownership clarity</h4><p className="muted">{ownershipStatus}</p><div className="signal-grid"><span>Missing records <b>{ownership?.missingOrPlaceholderObservationCount ?? safeDetail.ownershipQuality?.missingOrPlaceholderObservationCount ?? 0}</b></span><span>Valid candidates <b>{ownership?.observedOwnerCandidates?.length ?? safeDetail.ownershipQuality?.observedCandidates?.length ?? 0}</b></span><span>Conflict <b>{(ownership?.conflict ?? safeDetail.ownershipQuality?.conflict) ? "Yes" : "No"}</b></span><span>Assignment <b>{ownership?.assignmentResponsibility?.length ? ownership.assignmentResponsibility.map((item: any) => item.username).join(", ") : "None"}</b></span></div><details className="technical-details"><summary>View owner records</summary><div className="observation-list">{observations.map((row: any, index: number) => <div key={String(row?.id ?? index)}><span className="mono">{String(row?.id ?? "—")}</span><span>{String(row?.ownerNormalized ?? "Missing / placeholder")}</span><b>{String(row?.reportId ?? safeDetail.reportId)}</b></div>)}</div></details></section><section className="drawer-section"><h4>Source-backed findings</h4>{brief.confirmedFindings?.length ? <ul>{brief.confirmedFindings.map((item: string) => <li key={item}>{item}</li>)}</ul> : <p className="muted">No deterministic findings in the current authorized evaluation.</p>}<p className="muted">{brief.certainty ?? "Backend measurements are confirmed; possible causes remain unverified."}</p></section><section className="drawer-section"><h4>Source observations</h4><div className="observation-list">{observations.slice(0, 8).map((row: any, index: number) => <div key={String(row?.id ?? row?.sourceRowId ?? index)}><span className="mono">{String(row?.id ?? row?.sourceRowId ?? "—")}</span><span>{String(row?.refreshStatus ?? "—")}</span><b className={Number(row?.avgLoadTimeSec) > 15 ? "warning-text" : ""}>{fmt(row?.avgLoadTimeSec)}s</b></div>)}</div></section>{firstGroupId && <section className="drawer-section"><h4>Explainable RCA</h4><p className="muted">Request a source-backed investigation for this report when you need one.</p><RcaRequestButton token={token} groupId={firstGroupId} /></section>}<div className="drawer-actions"><button type="button" onClick={() => { close(); setPage("incidents"); }}>View alerts</button><button type="button" onClick={() => { close(); setPage("costs"); }}>View costs</button></div></Drawer>; }

function Incidents({ token, user, liveRevision }: { token: string; user: User; liveRevision: number }) { const [data, setData] = useState<any>(); const [filter, setFilter] = useState(""); const [ruleFilter, setRuleFilter] = useState("all"); const [statusFilter, setStatusFilter] = useState("all"); const [investigationFilter, setInvestigationFilter] = useState("all"); const [filtersOpen, setFiltersOpen] = useState(false); const [search, setSearch] = useState(""); const [selected, setSelected] = useState<any>(null); const [page, setPageNumber] = useState(1); const pageSize = workspacePageSize(); const activeFilterCount = Number(Boolean(filter)) + Number(ruleFilter !== "all") + Number(statusFilter !== "all") + Number(investigationFilter !== "all"); const refresh = () => request("/api/incidents?page=" + page + "&pageSize=" + pageSize + "&search=" + encodeURIComponent(search) + (filter ? "&severity=" + filter : "") + (ruleFilter !== "all" ? "&rule=" + encodeURIComponent(ruleFilter) : "") + (statusFilter !== "all" ? "&status=" + encodeURIComponent(statusFilter) : "") + (investigationFilter !== "all" ? "&investigation=" + encodeURIComponent(investigationFilter) : ""), {}, token).then(setData).catch(() => undefined); useEffect(() => { void refresh(); }, [token, search, filter, ruleFilter, statusFilter, investigationFilter, page, pageSize, liveRevision]); useEffect(() => { setPageNumber(1); setSelected(null); }, [filter, ruleFilter, statusFilter, investigationFilter, search]); const clearFilters = () => { setFilter(""); setRuleFilter("all"); setStatusFilter("all"); setInvestigationFilter("all"); }; return <>{!data ? <Loading /> : <section className="workspace-grid"><section className="table-card glass-panel"><div className="workspace-toolbar"><div><span className="eyebrow">DETERMINISTIC RULE ENGINE</span><h2>Alerts</h2><p>Every qualifying observation remains traceable to its source row.</p></div><div className="filter-bar"><div className="inline-search"><Search size={15} /><input value={search} onChange={event => setSearch(event.target.value)} placeholder="Search alerts" aria-label="Search alerts" /></div><select value={filter} onChange={event => setFilter(event.target.value)} aria-label="Filter alerts by severity"><option value="">All severities</option><option value="critical">Critical</option><option value="high">High</option><option value="medium">Medium</option></select><FilterMenu open={filtersOpen} onToggle={() => setFiltersOpen(value => !value)} onClear={clearFilters} activeCount={activeFilterCount}><label>Rule<select value={ruleFilter} onChange={event => setRuleFilter(event.target.value)}><option value="all">All rules</option><option value="LATENCY_OVER_15S">Latency over 15s</option><option value="REFRESH_FAILED">Refresh failed</option><option value="REFRESH_TIMED_OUT">Refresh timed out</option><option value="REFRESH_UNKNOWN">Unknown refresh</option><option value="ORPHANED_REPORT_OWNER">Missing owner</option><option value="NEGATIVE_CREDITS">Negative credits</option></select></label><label>Status<select value={statusFilter} onChange={event => setStatusFilter(event.target.value)}><option value="all">All statuses</option><option value="open">Open</option><option value="acknowledged">Acknowledged</option></select></label><label>Investigation<select value={investigationFilter} onChange={event => setInvestigationFilter(event.target.value)}><option value="all">All investigations</option><option value="not_queued">Not queued</option><option value="pending">Pending</option><option value="running">Running</option><option value="completed">Completed</option><option value="failed">Failed</option><option value="insufficient_evidence">Insufficient evidence</option></select></label></FilterMenu></div></div><div className="table-scroll"><table><thead><tr><th>Severity</th><th>Report / rule</th><th>Occurrences</th><th>Status</th><th>Investigation</th><th /></tr></thead><tbody>{data.data.map((row: any) => <tr key={row.id} onClick={() => setSelected(row)} className={selected?.id === row.id ? "selected" : ""}><td><span className={"severity-badge " + row.severity}><span /> {displayStatus(row.severity)}</span></td><td><strong>{row.reportId}</strong><small>{row.ruleCode} · {row.sessionId}</small></td><td>{row.occurrenceCount}</td><td><span className={"status-badge " + row.status}>{displayStatus(row.status)}</span></td><td><span className={"status-badge " + row.investigationStatus}>{displayStatus(row.investigationStatus)}</span></td><td><ChevronRight size={15} /></td></tr>)}</tbody></table></div><TablePagination page={data.page ?? page} pageSize={data.pageSize ?? pageSize} total={data.total ?? 0} onPageChange={nextPage => { setPageNumber(nextPage); setSelected(null); }} label="alerts" /></section>{selected && <InvestigationDrawer token={token} user={user} row={selected} liveRevision={liveRevision} close={() => setSelected(null)} refresh={refresh} />}</section>}</>; }
function RcaRequestButton({ token, groupId, status, onRequested }: { token: string; groupId?: string | null; status?: string | null; onRequested?: () => void }) { const [busy, setBusy] = useState(false); const [requested, setRequested] = useState(false); const [error, setError] = useState(""); if (!groupId) return null; const alreadyRequested = requested || ["pending", "running", "completed", "insufficient_evidence"].includes(String(status ?? "")); const submit = async () => { setBusy(true); setError(""); try { const result = await request("/api/incident-groups/" + encodeURIComponent(groupId) + "/rca", { method: "POST" }, token); setRequested(["pending", "running", "completed", "insufficient_evidence"].includes(String(result?.status ?? "pending"))); onRequested?.(); } catch (nextError) { setRequested(false); setError(nextError instanceof Error ? nextError.message : "RCA request was not accepted."); } finally { setBusy(false); } }; return <span className="rca-request-wrap"><button className="small-button rca-request-button" type="button" onClick={() => void submit()} disabled={busy || alreadyRequested}><Clock3 size={13} /> {busy ? "Requesting…" : alreadyRequested ? "RCA requested" : "Run AI Investigation"}</button>{error && <small className="drawer-inline-error" role="status">{error}</small>}</span>; }

function InvestigationDrawer({ token, user, row, close, refresh, liveRevision = 0 }: { token: string; user: User; row: any; close: () => void; refresh: () => void; liveRevision?: number }) {
  const [detail, setDetail] = useState<any>(row);
  const load = () => request("/api/incident-groups/" + encodeURIComponent(row.groupId ?? row.id), {}, token).then(data => setDetail({ ...row, ...data.group, members: data.members, rca: data.rca, rcaJob: data.rcaJob, investigationBrief: data.investigationBrief })).catch(() => undefined);
  useEffect(() => { void load(); }, [row.id, row.groupId, token, liveRevision]);
  const acknowledge = async () => { await request("/api/incidents/" + encodeURIComponent(row.groupId ?? row.id) + "/acknowledge", { method: "POST" }, token); refresh(); close(); };
  const rca = detail.rca;
  const rcaStatus = String(detail.rcaJob?.status ?? "not_queued");
  const rcaRequested = ["pending", "running", "completed", "insufficient_evidence", "failed"].includes(rcaStatus);
  const providerFailed = rcaStatus === "failed" || rca?.fallbackStatus === "provider_failed" || rca?.fallbackStatus === "validation_rejected" || rca?.validationOutcome === "rejected_fallback" || rca?.validationOutcome === "provider_failed";
  const deterministic = Boolean(rca && (rca.generatedBy === "deterministic" || rca.provider === "deterministic"));
  const brief = detail.investigationBrief ?? {};
  const supportedHypotheses = rca?.supportedHypotheses ?? rca?.potentialCauses ?? brief.possibleCauses ?? [];
  const recommendedChecks = rca?.recommendedNextSteps ?? brief.recommendedChecks ?? ["Inspect the source-backed evidence packet.", "Review the report-refresh logs and query execution profile."];
  return <Drawer title={detail.reportId ?? "Incident"} eyebrow="INCIDENT INVESTIGATION" close={close}>
    <div className="drawer-title-row"><div><span className={"severity-badge " + detail.severity}><span /> {detail.severity}</span><div className="drawer-subtitle">{String(detail.ruleCode ?? "Finding").replaceAll("_", " ")} · {detail.occurrenceCount ?? 1} preserved occurrence(s)</div></div><div className="drawer-action-stack"><RcaRequestButton token={token} groupId={detail.groupId ?? row.groupId} status={rcaStatus} onRequested={() => { void load(); }} />{user.role === "ADMIN" && detail.status === "open" && <button className="small-button" onClick={() => void acknowledge()}>Acknowledge</button>}</div></div>
    <section className="investigation-section"><h4>What happened</h4><p>{detail.ruleCode === "LATENCY_OVER_THRESHOLD" || detail.ruleCode === "LATENCY_OVER_15S" ? "A report observation exceeded the configured 15 second load-latency threshold." : "The source observation triggered the " + String(detail.ruleCode ?? "validation").replaceAll("_", " ") + " validation rule."}</p><div className="fact-grid"><span>Report <b>{detail.reportId}</b></span><span>Occurrences <b>{detail.occurrenceCount}</b></span><span>First seen <b>{detail.firstDetected ? new Date(detail.firstDetected).toLocaleString() : "—"}</b></span><span>Last seen <b>{detail.lastDetected ? new Date(detail.lastDetected).toLocaleString() : "—"}</b></span></div>{brief.confirmedFinding && <p className="muted">{brief.confirmedFinding}</p>}</section>
    <section className="investigation-section"><h4>What we know</h4><ul><li>Detection was produced by the backend rule engine.</li><li>Evidence remains linked to {detail.members?.length ?? 1} source observation(s).</li><li>The replay timestamp is simulated metadata, not source chronology.</li>{brief.measuredValue != null && <li>Measured value: {fmt(brief.measuredValue)} against {brief.threshold ?? "the configured rule threshold"}.</li>}</ul></section>
    <section className="investigation-section"><h4>Explainable RCA</h4>{!rcaRequested ? <p className="muted">RCA has not been requested. Select “Run explainable RCA” when you want an investigation for this record.</p> : providerFailed ? <p className="safe-note">RCA unavailable right now. Please try again later. The deterministic detection and source evidence remain available.</p> : !rca ? <p className="muted">RCA requested. Waiting for the analysis result…</p> : deterministic ? <><p className="safe-note">Deterministic fallback: confirmed findings come from source observations; no AI causal conclusion was accepted.</p><ul>{(rca.confirmedFindings ?? []).map((item: string) => <li key={item}>{item}</li>)}</ul></> : <><p className="safe-note">These are policy-approved investigation hypotheses, not confirmed infrastructure causes.</p><ul>{supportedHypotheses.map((item: string) => <li key={item}>{item}</li>)}</ul></>}</section>
    <section className="investigation-section"><h4>Suggested diagnostics</h4><ul>{recommendedChecks.map((item: string) => <li key={item}>{item}</li>)}</ul></section>
    <details className="technical-details"><summary>Analysis information</summary><pre>{JSON.stringify({ incidentGroupId: detail.groupId ?? row.groupId ?? row.id, sessionId: detail.sessionId, rcaJobId: detail.rcaJob?.job_id, sourceObservationIds: (detail.members ?? []).map((member: any) => member.observation?.id), evidenceRefs: rca?.evidenceRefs, evidenceVersion: rca?.analyzedEvidenceHash, provider: rca?.provider, model: rca?.model, validationOutcome: rca?.validationOutcome, generatedBy: rca?.generatedBy, fallbackStatus: rca?.fallbackStatus, toolsUsed: rca?.toolsUsed }, null, 2)}</pre></details>
  </Drawer>;
}


function Costs({ token, liveRevision }: { token: string; liveRevision: number }) { const [data, setData] = useState<any>(); const [analytics, setAnalytics] = useState<any>(); const [recordModal, setRecordModal] = useState<"invalid" | "zero" | null>(null); useEffect(() => { Promise.all([request("/api/costs", {}, token), request("/api/analytics", {}, token)]).then(([nextCosts, nextAnalytics]) => { setData(nextCosts); setAnalytics(nextAnalytics); }).catch(() => undefined); }, [token, liveRevision]); if (!data || !analytics) return <Loading />; const awsRankedReports = Array.isArray(data.topAwsReports) ? data.topAwsReports : data.topReports; const costData = awsRankedReports.slice(0, 8).map((row: any) => ({ report: row.reportId.replace("RPT-", ""), aws: row.medianAwsCostPerActiveViewUsd ?? 0 })); return <><div className="metric-grid"><CostMetricCard label="Valid credit rows" value={data.validCreditObservations} detail="Rows eligible for Snowflake cost allocation." icon={CheckCircle2} /><CostMetricCard label="Invalid credit rows" value={data.invalidCreditObservations} detail="Rows excluded because Snowflake credits are negative." icon={AlertCircle} tone="red" onClick={() => setRecordModal("invalid")} /><CostMetricCard label="Zero-view rows" value={data.zeroViewObservations} detail="Rows where cost per view cannot be calculated." icon={CircleDollarSign} tone="orange" onClick={() => setRecordModal("zero")} /><CostMetricCard label="AWS outlier reviews" value={data.costUsageQuality?.flaggedReports?.length ?? 0} detail="Reports with unusually high AWS cost per view." icon={CircleDollarSign} tone="violet" /></div><div className="cost-grid"><section className="chart-card glass-panel"><div className="panel-header"><div><span className="eyebrow">REPORT-LEVEL MEDIANS</span><h2>AWS cost per active view</h2><p>No contractual baseline is assumed.</p></div><Cloud size={18} className="panel-icon" /></div><div className="chart-wrap"><ResponsiveContainer width="100%" height="100%"><BarChart data={costData}><CartesianGrid vertical={false} stroke="#e5efec" /><XAxis dataKey="report" axisLine={false} tickLine={false} tick={{ fill: "#7a918c", fontSize: 11 }} /><YAxis axisLine={false} tickLine={false} tick={{ fill: "#7a918c", fontSize: 11 }} /><Tooltip /><Bar dataKey="aws" fill="#2f9f95" radius={[6, 6, 0, 0]} /></BarChart></ResponsiveContainer></div></section><section className="chart-card glass-panel"><div className="panel-header"><div><span className="eyebrow">SNOWFLAKE VALIDITY</span><h2>Latency and credit context</h2><p>Source-backed observations, not totals over repeated IDs.</p></div><BarChart3 size={18} className="panel-icon" /></div><div className="chart-wrap"><ResponsiveContainer width="100%" height="100%"><AreaChart data={analytics.latencyDistribution}><defs><linearGradient id="latencyFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#f39b5c" stopOpacity={0.45} /><stop offset="100%" stopColor="#f39b5c" stopOpacity={0.04} /></linearGradient></defs><CartesianGrid vertical={false} stroke="#e5efec" /><XAxis dataKey="bucket" axisLine={false} tickLine={false} tick={{ fill: "#7a918c", fontSize: 11 }} /><YAxis axisLine={false} tickLine={false} tick={{ fill: "#7a918c", fontSize: 11 }} /><Tooltip /><Area type="monotone" dataKey="count" stroke="#e98a40" strokeWidth={2.5} fill="url(#latencyFill)" /></AreaChart></ResponsiveContainer></div></section></div><section className="flag-card glass-panel"><div className="panel-header"><div><span className="eyebrow">DATA QUALITY REVIEW</span><h2>AWS cost versus usage</h2><p>{data.costUsageQuality?.method}</p></div><span className="status-badge review">Review only</span></div>{data.costUsageQuality?.flaggedReports?.length ? <div className="flag-list">{data.costUsageQuality.flaggedReports.map((flag: any) => <div key={flag.reportId}><strong>{flag.reportId}</strong><span>{money(flag.medianAwsCostPerActiveViewUsd, 4)} per active view</span><small>{flag.reason}</small></div>)}</div> : <Empty text="No report-level AWS cost-per-view outliers under the configured reproducible rule." />}</section>{recordModal && <CostRecordModal token={token} kind={recordModal} rows={recordModal === "invalid" ? data.invalidCreditRows ?? [] : data.zeroViewRows ?? []} close={() => setRecordModal(null)} />}</>; }

function CostMetricCard({ label, value, detail, help, analysis, icon: Icon, tone = "teal", onClick }: { label: string; value: unknown; detail: string; help?: string; analysis?: string; icon: typeof Activity; tone?: string; onClick?: () => void }) { const explanations: Record<string, [string, string]> = { "Valid credit rows": ["Counts source rows with non-negative Snowflake credits that can enter allocation.", "Analysis: valid rows available for credit-per-view calculations."], "Invalid credit rows": ["Shows preserved rows excluded because their Snowflake credit value is negative.", "Analysis: invalid-credit observations kept out of Snowflake allocation."], "Zero-view rows": ["Shows rows with zero active views, so cost per view stays safely null.", "Analysis: zero denominators are preserved without unsafe division."], "AWS outlier reviews": ["Flags unusually high AWS cost per active view for human review.", "Analysis: report-level median outliers, not confirmed accounting errors."] }; const [defaultHelp, defaultAnalysis] = explanations[label] ?? [detail, "Analysis: source-backed cost and data-quality metric."]; const helpText = help ?? defaultHelp; const analysisText = analysis ?? defaultAnalysis; const content = <><div className="metric-top"><span>{label}</span><span className="metric-icon"><Icon size={17} /></span></div><strong>{fmt(value, 0)}</strong><small>{detail}</small>{onClick && <span className="metric-card-action">View records <ChevronRight size={12} /></span>}<span className="metric-card-help" aria-label={"About " + label}><CircleHelp size={13} aria-hidden="true" /><span className="metric-card-help-popover" role="tooltip"><strong>{helpText}</strong><span>{analysisText}</span></span></span></> ; return onClick ? <button type="button" className={"metric-card glass-panel " + tone + " metric-card--interactive"} onClick={onClick}>{content}</button> : <article className={"metric-card glass-panel " + tone}>{content}</article>; }
function CostRecordModal({ token, kind, rows, close }: { token: string; kind: "invalid" | "zero"; rows: any[]; close: () => void }) { useEffect(() => { const previousOverflow = document.body.style.overflow; document.body.style.overflow = "hidden"; const onKey = (event: KeyboardEvent) => { if (event.key === "Escape") close(); }; window.addEventListener("keydown", onKey); return () => { document.body.style.overflow = previousOverflow; window.removeEventListener("keydown", onKey); }; }, [close]); const title = kind === "invalid" ? "Invalid credit rows" : "Zero-view rows"; const explanation = kind === "invalid" ? "These rows are excluded from Snowflake credit allocation because the source credits are negative." : "These rows are preserved, but cost per view is null because dividing by zero views is unsafe."; return <div className="cost-record-modal-scrim" onMouseDown={event => { if (event.currentTarget === event.target) close(); }}><section className="cost-record-modal" role="dialog" aria-modal="true" aria-labelledby="cost-record-modal-title"><header><div><span className="eyebrow">SOURCE DATA REVIEW</span><h2 id="cost-record-modal-title">{title}</h2><p>{explanation}</p></div><button className="modal-close" onClick={close} aria-label="Close source data review"><X size={18} /></button></header><div className="cost-record-list">{rows.length ? rows.map((row: any) => <div className="cost-record-row" key={String(row.id ?? row.sourceRowId)}><span><strong>{row.reportId}</strong><small>{row.sourceRowId ?? row.id} · {row.refreshStatus ?? "source observation"}</small></span><span><b>{kind === "invalid" ? `${fmt(row.snowflakeCredits)} credits` : `${fmt(row.monthlyActiveViews, 0)} views`}</b><small>{money(row.awsHostingCostUsd, 4)} AWS cost</small>{row.groupId && <RcaRequestButton token={token} groupId={row.groupId} />}</span></div>) : <Empty text="No matching source rows in the current replay scope." />}</div><footer><button className="secondary-modal-action" onClick={close}>Close</button></footer></section></div>; }
function Drawer({ title, eyebrow, close, children }: { title: string; eyebrow: string; close: () => void; children: ReactNode }) { useEffect(() => { const previousOverflow = document.body.style.overflow; document.body.style.overflow = "hidden"; const onKey = (event: KeyboardEvent) => { if (event.key === "Escape") close(); }; window.addEventListener("keydown", onKey); return () => { document.body.style.overflow = previousOverflow; window.removeEventListener("keydown", onKey); }; }, [close]); return <div className="detail-modal-scrim" onMouseDown={event => { if (event.currentTarget === event.target) close(); }}><section className="detail-modal" role="dialog" aria-modal="true" aria-labelledby="detail-modal-title"><div className="drawer-header"><div><span className="eyebrow">{eyebrow}</span><h2 id="detail-modal-title">{title}</h2></div><button className="drawer-close" onClick={close} aria-label="Close inspector"><X size={19} /></button></div><div className="drawer-body">{children}</div></section></div>; }
function DrawerStat({ label, value, tone = "" }: { label: string; value: string; tone?: string }) { return <div className={"drawer-stat " + tone}><span>{label}</span><strong>{value}</strong></div>; }
function Loading() { return <div className="dashboard-loading" role="status" aria-live="polite"><span className="loading-orbit" aria-hidden="true"><span className="loading-spinner" /></span><strong>Preparing your workspace</strong><span>Loading source-backed telemetry…</span></div>; }
function Empty({ text }: { text: string }) { return <div className="empty-state">{text}</div>; }

function OverviewPremium({ token, setPage, live, liveRevision, user, autoStartReplay = false, onReplayStarted, streamStatus }: { token: string; setPage: (page: Page) => void; live: LiveEvent[]; liveRevision: number; user: User; autoStartReplay?: boolean; onReplayStarted?: () => void; streamStatus?: StreamStatus }) {
  const [data, setData] = useState<any>(); const [analytics, setAnalytics] = useState<any>(); const [costs, setCosts] = useState<any>(); const [reports, setReports] = useState<any[]>([]); const [selectedReport, setSelectedReport] = useState<any>(null); const [selectedIncident, setSelectedIncident] = useState<any>(null); const [expandedChart, setExpandedChart] = useState(false);
  useEffect(() => { let cancelled = false; const refresh = () => Promise.all([request("/api/overview", {}, token), request("/api/analytics", {}, token), request("/api/costs", {}, token), request("/api/reports?page=1&pageSize=100", {}, token)]).then(([overview, nextAnalytics, nextCosts, nextReports]) => { if (!cancelled) { setData(overview); setAnalytics(nextAnalytics); setCosts(nextCosts); setReports(nextReports.data ?? []); } }).catch(() => undefined); void refresh(); const timer = window.setInterval(refresh, 2600); return () => { cancelled = true; window.clearInterval(timer); }; }, [token, liveRevision]);
  if (!data || !analytics || !costs) return <Loading />;
  const categories = analytics.findingsByCategory ?? []; const reviewReports = analytics.topLatencyReports?.slice(0, 5) ?? []; const alerts = data.recentIncidents?.slice(0, 5) ?? []; const flagged = (costs.costUsageQuality?.flaggedReports?.length ?? 0) + (data.invalidCredits ?? 0); const validPercent = costs.observationCount ? Math.round((costs.validCreditObservations / costs.observationCount) * 100) : 0; const reportReviewCount = new Set(reports.filter(report => report.maxLatencySec > 15 || report.orphanedObservations > 0 || Object.keys(report.refreshStatusCounts ?? {}).some(key => ["FAILED", "TIMED_OUT", "UNKNOWN"].includes(key))).map(report => report.reportId)).size;
  return <div className="overview-premium"><div className="overview-header"><div><span className="breadcrumb">SIGNALGRID / OVERVIEW</span><h1>Overview</h1><p>Source-backed operational health at a glance.</p></div><span className="simulated-badge"><Activity size={14} /> Simulated telemetry</span></div><div className="overview-kpis"><OverviewKpi label="Reports monitored" value={data.reports} detail={fmt(data.observations, 0) + " source observations"} tone="teal" icon={Database} segments={Math.min(24, Math.round((data.reports / 100) * 24))} onClick={() => setPage("reports")} /><OverviewKpi label="Reports needing review" value={reportReviewCount} detail="Grouped from deterministic findings" tone="orange" icon={AlertTriangle} segments={Math.min(24, Math.max(3, Math.round((reportReviewCount / Math.max(1, data.reports)) * 24)))} onClick={() => setPage("reports")} /><OverviewKpi label="Active alerts" value={data.groupedIncidents} detail={fmt(data.detectionEvents ?? 0, 0) + " detections preserved"} tone="violet" icon={Zap} segments={Math.min(24, Math.max(3, Math.round((data.groupedIncidents / Math.max(1, data.reports)) * 24)))} onClick={() => setPage("incidents")} /><OverviewKpi label="Data-quality flags" value={flagged} detail={(costs.costUsageQuality?.flaggedReports?.length ?? 0) + " AWS reviews · " + (data.invalidCredits ?? 0) + " invalid credits"} tone="red" icon={CircleDollarSign} segments={Math.min(24, Math.max(3, Math.round((flagged / Math.max(1, data.observations)) * 24)))} onClick={() => setPage("costs")} /></div><div className="overview-analytics-grid"><section className="overview-panel chart-panel"><div className="overview-panel-header"><div><span className="eyebrow">REPORT HEALTH OVERVIEW</span><h2>Load latency distribution</h2><p>Source observations grouped around the 15 second review threshold.</p></div><button className="panel-expand-button" onClick={() => setExpandedChart(true)} aria-label="Expand latency distribution"><MoreHorizontal size={18} /></button></div><div className="overview-chart chart-large"><ResponsiveContainer width="100%" height="100%"><BarChart data={analytics.latencyDistribution} barCategoryGap="18%"><CartesianGrid vertical={false} stroke="#edf0ef" strokeDasharray="4 5" /><XAxis dataKey="bucket" axisLine={false} tickLine={false} tick={{ fill: "#87928f", fontSize: 11 }} /><YAxis axisLine={false} tickLine={false} tick={{ fill: "#87928f", fontSize: 11 }} /><Tooltip cursor={{ fill: "#f5f8f7" }} contentStyle={{ border: "1px solid #e5eae8", borderRadius: 10, boxShadow: "0 12px 28px rgba(32,53,48,.1)", fontFamily: "Onest" }} /><Bar dataKey="count" name="Observations" radius={[8, 8, 2, 2]}>{analytics.latencyDistribution.map((item: any, index: number) => <Cell key={item.bucket} fill={item.bucket === "15–30s" ? "#ee9955" : item.bucket === "30s+" ? "#de6258" : index === 1 ? "#84cfc2" : "#56b7a5"} />)}</Bar></BarChart></ResponsiveContainer></div><div className="chart-footnote"><span><i className="legend-dot teal-dot" /> At or below 15s</span><span><i className="legend-dot orange-dot" /> Alert eligible above 15s</span><button onClick={() => setPage("reports")}>View reports <ChevronRight size={14} /></button></div></section><section className="overview-panel risk-panel"><div className="overview-panel-header"><div><span className="eyebrow">RISK DISTRIBUTION</span><h2>Where attention is needed</h2><p>Unique reports by source-backed finding.</p></div></div><div className="risk-bars">{categories.map((category: any, index: number) => { const colors = ["#ee9955", "#e95068", "#9177e5", "#18b29f"]; const icons = [Gauge, RefreshCw, UserRound, CircleDollarSign]; const color = colors[index % colors.length]; const RiskIcon = icons[index % icons.length]; return <button className="risk-bar-row" key={category.category} onClick={() => setPage(category.category === "Invalid Credits" ? "costs" : "incidents")}><span className="risk-bar-icon" style={{ color, background: color + "18" }}><RiskIcon size={16} /></span><span className="risk-bar-label"><b>{category.category}</b><small>{category.count} reports</small></span><span className="risk-bar-track"><i style={{ width: Math.min(100, Math.max(8, (category.count / Math.max(1, data.reports)) * 100) ) + "%", background: color }} /></span><ChevronRight size={15} /></button>; })}</div><div className="risk-panel-footer"><span>Click a category to inspect the relevant workspace</span></div></section></div><div className="overview-detail-grid"><section className="overview-panel review-panel"><div className="overview-panel-header"><div><span className="eyebrow">PRIORITIZED REPORTS</span><h2>Reports to review</h2><p>Highest observed latency from preserved source rows.</p></div><button className="text-action" onClick={() => setPage("reports")}>View all <ChevronRight size={14} /></button></div><div className="report-review-list">{reviewReports.map((report: any, index: number) => <button className="report-review-row" key={report.reportId} onClick={() => setSelectedReport(report)}><span className={"report-symbol report-symbol--" + (index % 4)}><FileSearch size={16} /></span><span className="report-review-main"><strong>{report.reportId}</strong><small>{report.reportName ?? "Source report"}</small></span><span className="report-review-stat"><i style={{ width: Math.min(100, Math.max(15, (report.maxLatencySec / 60) * 100)) + "%" }} /><small>{fmt(report.maxLatencySec)}s peak</small></span><span className="report-review-status">{report.maxLatencySec >= 30 ? "Critical" : "Review"}</span><ChevronRight size={15} /></button>)}</div></section><section className="overview-panel cost-overview-panel"><div className="overview-panel-header"><div><span className="eyebrow">CLOUD COST OVERVIEW</span><h2>Credit validity</h2><p>Rows eligible for Snowflake allocation.</p></div><button className="panel-icon-link" onClick={() => setPage("costs")} aria-label="Open cloud costs"><Cloud size={18} /></button></div><div className="validity-gauge"><div className="validity-gauge-arc" style={{ "--validity": validPercent + "%" } as React.CSSProperties}><span>{validPercent}%</span></div></div><div className="cost-overview-footer"><span><b>{fmt(costs.validCreditObservations, 0)}</b> valid rows</span><span><b>{fmt(costs.invalidCreditObservations, 0)}</b> excluded</span></div><button className="full-width-action" onClick={() => setPage("costs")}>Open cost analysis <ChevronRight size={14} /></button></section><section className="overview-panel alerts-overview-panel"><div className="overview-panel-header"><div><span className="eyebrow">RECENT ALERTS</span><h2>Active investigations</h2><p>Persisted incidents and live replay updates.</p></div><button className="text-action" onClick={() => setPage("incidents")}>View all <ChevronRight size={14} /></button></div><div className="alert-review-list">{alerts.length ? alerts.map((alert: any) => <button className="alert-review-row" key={String(alert.id)} onClick={() => setSelectedIncident(alert)}><span className={"alert-severity-dot " + String(alert.severity).toLowerCase()} /><span><strong>{alert.reportId}</strong><small>{String(alert.ruleCode ?? "Finding").replaceAll("_", " ")}</small></span><span className="alert-state">{displayStatus(alert.investigationStatus ?? alert.status ?? "open")}</span><ChevronRight size={14} /></button>) : <Empty text="No persisted alerts yet. Start a full replay to see incidents arrive." />}</div></section></div><div className="overview-replay"><ReplayControls token={token} user={user} compact autoStart={autoStartReplay} onReplayStarted={onReplayStarted} streamStatus={streamStatus} /></div>{selectedReport && <ReportInspector token={token} report={selectedReport} close={() => setSelectedReport(null)} setPage={setPage} />}{selectedIncident && <InvestigationDrawer token={token} user={user} row={selectedIncident} close={() => setSelectedIncident(null)} refresh={() => undefined} />}{expandedChart && <AnalyticsModal analytics={analytics} close={() => setExpandedChart(false)} setPage={setPage} />}</div>;
}

function Overview({ token, setPage, live, liveRevision, user, autoStartReplay = false, onReplayStarted, streamStatus }: { token: string; setPage: (page: Page) => void; live: LiveEvent[]; liveRevision: number; user: User; autoStartReplay?: boolean; onReplayStarted?: () => void; streamStatus?: StreamStatus }) { return <OverviewPremium token={token} setPage={setPage} live={live} liveRevision={liveRevision} user={user} autoStartReplay={autoStartReplay} onReplayStarted={onReplayStarted} streamStatus={streamStatus} />; }

function OverviewKpi({ label, value, detail, tone, icon: Icon, segments, onClick }: { label: string; value: unknown; detail: string; tone: string; icon: typeof Activity; segments: number; onClick: () => void }) { return <button className={"overview-kpi overview-kpi--" + tone} onClick={onClick}><div className="overview-kpi-top"><span>{label}</span><span className="overview-kpi-icon"><Icon size={17} /></span></div><strong>{fmt(value, 0)}</strong><small>{detail}</small><span className="kpi-segments" aria-hidden="true">{Array.from({ length: 24 }, (_, index) => <i key={index} className={index < segments ? "filled" : ""} />)}</span><span className="overview-kpi-arrow" aria-hidden="true"><ChevronRight size={12} /></span></button>; }

function AnalyticsModal({ analytics, close, setPage }: { analytics: any; close: () => void; setPage: (page: Page) => void }) { useEffect(() => { const previousOverflow = document.body.style.overflow; document.body.style.overflow = "hidden"; const onKey = (event: KeyboardEvent) => { if (event.key === "Escape") close(); }; window.addEventListener("keydown", onKey); return () => { document.body.style.overflow = previousOverflow; window.removeEventListener("keydown", onKey); }; }, [close]); return <div className="analytics-modal-scrim" onMouseDown={event => { if (event.currentTarget === event.target) close(); }}><section className="analytics-modal" role="dialog" aria-modal="true" aria-labelledby="latency-modal-title"><header><div><span className="eyebrow">EXPANDED ANALYSIS</span><h2 id="latency-modal-title">Load latency distribution</h2><p>Every bar represents preserved source observations; replay timestamps are not source chronology.</p></div><button className="modal-close" onClick={close} aria-label="Close expanded analysis"><X size={18} /></button></header><div className="modal-toolbar"><span className="modal-tab active">All observations</span><span className="modal-threshold">Review threshold <b>15s</b></span></div><div className="modal-chart"><ResponsiveContainer width="100%" height="100%"><BarChart data={analytics.latencyDistribution} barCategoryGap="14%"><CartesianGrid vertical={false} stroke="#edf0ef" strokeDasharray="4 5" /><XAxis dataKey="bucket" axisLine={false} tickLine={false} tick={{ fill: "#7c8884", fontSize: 12 }} /><YAxis axisLine={false} tickLine={false} tick={{ fill: "#7c8884", fontSize: 12 }} /><Tooltip contentStyle={{ border: "1px solid #e5eae8", borderRadius: 10, fontFamily: "Onest" }} /><Bar dataKey="count" name="Observations" radius={[9, 9, 2, 2]}>{analytics.latencyDistribution.map((item: any, index: number) => <Cell key={item.bucket} fill={item.bucket === "15–30s" ? "#ee9955" : item.bucket === "30s+" ? "#de6258" : index === 1 ? "#84cfc2" : "#56b7a5"} />)}</Bar></BarChart></ResponsiveContainer></div><div className="modal-summary"><span><small>Total observations</small><b>{analytics.latencyDistribution.reduce((sum: number, item: any) => sum + item.count, 0).toLocaleString()}</b></span><span><small>Above threshold</small><b>{analytics.latencyDistribution.filter((item: any) => ["15–30s", "30s+"].includes(item.bucket)).reduce((sum: number, item: any) => sum + item.count, 0).toLocaleString()}</b></span><span><small>Interpretation</small><b>Review evidence</b></span></div><footer><button className="secondary-modal-action" onClick={close}>Close</button><button className="primary-modal-action" onClick={() => { close(); setPage("reports"); }}>Open reports <ChevronRight size={15} /></button></footer></section></div>; }
